<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>VoltSeal Hybrid Savings Calculator</title>
<script src="https://cdn.tailwindcss.com"></script>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
  html,body{font-family:'Inter',ui-sans-serif,system-ui,sans-serif;}
  .tnum{font-variant-numeric:tabular-nums;}
  input[type=number]::-webkit-outer-spin-button,input[type=number]::-webkit-inner-spin-button{-webkit-appearance:none;margin:0;}
  input[type=number]{-moz-appearance:textfield;}
  .left-grad{background:linear-gradient(160deg,#0E3B2E 0%,#184D3B 60%,#0E3B2E 100%);}
  .kpi{box-shadow:0 4px 20px -8px rgba(14,59,46,.15);}
  .input-card{box-shadow:0 6px 24px -12px rgba(0,0,0,.25);}
  .err{transition:all .2s ease;overflow:hidden;}
</style>
</head>
<body class="bg-[#F7F3EC] text-[#0E3B2E]">
<div class="mx-auto flex min-h-screen max-w-[1600px] flex-col lg:flex-row">
  <aside class="left-grad flex w-full flex-col p-6 lg:w-[35%] lg:p-8">
    <div class="p-6">
      <img src="data:image/png;base64," alt="VoltSeal" style="max-width:220px;height:auto;object-fit:contain;display:block;" />
    </div>
    <div class="mt-6 flex flex-col gap-4">
      <!-- Power -->
      <div class="input-card rounded-2xl bg-white p-4">
        <div class="mb-2 flex items-baseline justify-between">
          <label class="text-sm font-semibold text-[#0E3B2E]">Power Requirement</label>
          <span class="text-xs font-medium uppercase tracking-wider text-neutral-500">kW</span>
        </div>
        <input id="power" type="number" min="0" step="0.01" value="500" placeholder="500"
          class="tnum w-full rounded-lg border border-neutral-200 bg-neutral-50/60 px-3 py-2.5 text-lg font-semibold text-[#0E3B2E] outline-none focus:border-[#184D3B] focus:bg-white focus:ring-2 focus:ring-[#184D3B]/20" />
      </div>
      <!-- Solar -->
      <div class="input-card rounded-2xl bg-white p-4">
        <div class="mb-2 flex items-baseline justify-between">
          <label class="text-sm font-semibold text-[#0E3B2E]">Solar + BESS vs Grid Usage</label>
          <span class="text-xs font-medium uppercase tracking-wider text-neutral-500">Hours</span>
        </div>
        <input id="solar" type="number" min="0" max="4" step="0.01" value="2" placeholder="2"
          class="tnum w-full rounded-lg border border-neutral-200 bg-neutral-50/60 px-3 py-2.5 text-lg font-semibold text-[#0E3B2E] outline-none focus:border-[#184D3B] focus:bg-white focus:ring-2 focus:ring-[#184D3B]/20" />
        <div id="solarErr" class="err mt-0 max-h-0 opacity-0 text-[13px] font-medium text-[#DC2626]"></div>
      </div>
      <!-- DG hrs -->
      <div class="input-card rounded-2xl bg-white p-4">
        <div class="mb-2 flex items-baseline justify-between">
          <label class="text-sm font-semibold text-[#0E3B2E]">BESS vs DG Usage</label>
          <span class="text-xs font-medium uppercase tracking-wider text-neutral-500">Hours</span>
        </div>
        <input id="dg" type="number" min="0" max="4" step="0.01" value="2" placeholder="2"
          class="tnum w-full rounded-lg border border-neutral-200 bg-neutral-50/60 px-3 py-2.5 text-lg font-semibold text-[#0E3B2E] outline-none focus:border-[#184D3B] focus:bg-white focus:ring-2 focus:ring-[#184D3B]/20" />
        <div id="dgErr" class="err mt-0 max-h-0 opacity-0 text-[13px] font-medium text-[#DC2626]"></div>
      </div>
      <!-- Days -->
      <div class="input-card rounded-2xl bg-white p-4">
        <div class="mb-2 flex items-baseline justify-between">
          <label class="text-sm font-semibold text-[#0E3B2E]">DG Operational Days</label>
          <span class="text-xs font-medium uppercase tracking-wider text-neutral-500">Days</span>
        </div>
        <input id="days" type="number" min="1" max="365" step="1" value="250" placeholder="250"
          class="tnum w-full rounded-lg border border-neutral-200 bg-neutral-50/60 px-3 py-2.5 text-lg font-semibold text-[#0E3B2E] outline-none focus:border-[#184D3B] focus:bg-white focus:ring-2 focus:ring-[#184D3B]/20" />
        <div id="daysErr" class="err mt-0 max-h-0 opacity-0 text-[13px] font-medium text-[#DC2626]"></div>
      </div>
    </div>
    <div class="mt-auto pt-8 text-xs text-white/50">© <span id="yr"></span> VoltSeal Energy</div>
  </aside>

  <main class="flex-1 p-6 lg:p-10">
    <header class="mb-6">
      <h1 class="text-2xl font-bold tracking-tight text-[#0E3B2E]">Hybrid Savings Calculator</h1>
      <p class="mt-1 text-sm text-neutral-600">Executive dashboard — Solar + BESS vs Grid &amp; BESS vs DG</p>
    </header>

    <div class="grid grid-cols-1 gap-4 md:grid-cols-3">
      <div class="kpi flex flex-col justify-center rounded-[20px] bg-white p-5 ring-1 ring-black/[0.03]">
        <div id="k_total" class="tnum whitespace-nowrap text-[clamp(1.6rem,2.6vw,2.6rem)] font-bold leading-tight tracking-tight text-[#0E3B2E]"></div>
        <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">Total Annual Savings</div>
      </div>
      <div class="kpi flex flex-col justify-center rounded-[20px] bg-white p-5 ring-1 ring-black/[0.03]">
        <div id="k_payY" class="tnum whitespace-nowrap text-[clamp(1.6rem,2.6vw,2.6rem)] font-bold leading-tight tracking-tight text-[#0E3B2E]"></div>
        <div id="k_payM" class="mt-0.5 whitespace-nowrap text-sm font-medium text-[#184D3B]/70"></div>
        <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">Payback Period</div>
      </div>
      <div class="kpi flex flex-col justify-center rounded-[20px] bg-white p-5 ring-1 ring-black/[0.03]">
        <div id="k_net" class="tnum whitespace-nowrap text-[clamp(1.6rem,2.6vw,2.6rem)] font-bold leading-tight tracking-tight text-[#0E3B2E]"></div>
        <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">Net Profit After 10 Years</div>
      </div>
    </div>

    <div class="mt-4 grid grid-cols-1 gap-4 md:grid-cols-3">
      <div class="kpi flex flex-col justify-center rounded-[20px] bg-white p-5 ring-1 ring-black/[0.03]">
        <div id="k_solarSav" class="tnum whitespace-nowrap text-[clamp(1.35rem,2vw,2rem)] font-bold leading-tight tracking-tight text-[#0E3B2E]"></div>
        <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">Solar + BESS vs Grid Savings</div>
      </div>
      <div class="kpi flex flex-col justify-center rounded-[20px] bg-white p-5 ring-1 ring-black/[0.03]">
        <div id="k_dgSav" class="tnum whitespace-nowrap text-[clamp(1.35rem,2vw,2rem)] font-bold leading-tight tracking-tight text-[#0E3B2E]"></div>
        <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">BESS vs DG Savings</div>
      </div>
      <div class="kpi flex flex-col justify-center rounded-[20px] bg-white p-5 ring-1 ring-black/[0.03]">
        <div id="k_bess" class="tnum whitespace-nowrap text-[clamp(1.35rem,2vw,2rem)] font-bold leading-tight tracking-tight text-[#0E3B2E]"></div>
        <div class="mt-0.5 whitespace-nowrap text-sm font-medium text-[#184D3B]/70">kWh</div>
        <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">Required BESS Size</div>
      </div>
    </div>

    <div class="mt-4 grid grid-cols-1 gap-4 md:grid-cols-3">
      <div class="kpi flex flex-col justify-center rounded-[20px] bg-white p-5 ring-1 ring-black/[0.03]">
        <div id="k_capex" class="tnum whitespace-nowrap text-[clamp(1.35rem,2vw,2rem)] font-bold leading-tight tracking-tight text-[#0E3B2E]"></div>
        <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">CAPEX</div>
      </div>
      <div class="kpi flex flex-col justify-center rounded-[20px] bg-white p-5 ring-1 ring-black/[0.03]">
        <div id="k_solarE" class="tnum whitespace-nowrap text-[clamp(1.15rem,1.6vw,1.6rem)] font-bold leading-tight tracking-tight text-[#0E3B2E]"></div>
        <div class="mt-0.5 whitespace-nowrap text-sm font-medium text-[#184D3B]/70">kWh / year</div>
        <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">Solar Energy Saved</div>
      </div>
      <div class="kpi flex flex-col justify-center rounded-[20px] bg-white p-5 ring-1 ring-black/[0.03]">
        <div id="k_dgE" class="tnum whitespace-nowrap text-[clamp(1.15rem,1.6vw,1.6rem)] font-bold leading-tight tracking-tight text-[#0E3B2E]"></div>
        <div class="mt-0.5 whitespace-nowrap text-sm font-medium text-[#184D3B]/70">kWh / year</div>
        <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">DG Energy Saved</div>
      </div>
    </div>

    <p class="mt-8 text-xs text-neutral-500">Assumption: Diesel generation cost considered at ₹32 per kWh.</p>
  </main>
</div>

<script>
document.getElementById('yr').textContent = new Date().getFullYear();
const MAX=4;
const $ = id => document.getElementById(id);
const power=$('power'), solar=$('solar'), dg=$('dg'), days=$('days');
const solarErr=$('solarErr'), dgErr=$('dgErr'), daysErr=$('daysErr');

function setErr(el,msg){
  if(msg){ el.textContent=msg; el.style.maxHeight='40px'; el.style.opacity='1'; el.style.marginTop='6px'; }
  else { el.textContent=''; el.style.maxHeight='0'; el.style.opacity='0'; el.style.marginTop='0'; }
}
function fmtINR(n){
  if(!isFinite(n)) return '0';
  const r=Math.round(n); const neg=r<0; const s=Math.abs(r).toString();
  if(s.length<=3) return (neg?'-':'')+s;
  const last3=s.slice(-3), rest=s.slice(0,-3);
  return (neg?'-':'')+rest.replace(/\B(?=(\d{2})+(?!\d))/g,',')+','+last3;
}
function fmtNum(n,d){ if(!isFinite(n)) return '0'; return n.toLocaleString('en-IN',{minimumFractionDigits:d,maximumFractionDigits:d}); }

function handleSolar(){
  setErr(dgErr,'');
  if(solar.value===''){ setErr(solarErr,''); calc(); return; }
  let n=parseFloat(solar.value); if(isNaN(n)||n<0){ calc(); return; }
  let msg='';
  if(n>4){ n=4; msg='Maximum usage allowed is 4 hours.'; solar.value=n; }
  const other=parseFloat(dg.value)||0;
  if(n+other>MAX){ dg.value=Math.max(0,MAX-n); msg='Combined maximum usage across both scenarios is 4 hours.'; }
  setErr(solarErr,msg); calc();
}
function handleDg(){
  setErr(solarErr,'');
  if(dg.value===''){ setErr(dgErr,''); calc(); return; }
  let n=parseFloat(dg.value); if(isNaN(n)||n<0){ calc(); return; }
  let msg='';
  if(n>4){ n=4; msg='Maximum usage allowed is 4 hours.'; dg.value=n; }
  const other=parseFloat(solar.value)||0;
  if(n+other>MAX){ solar.value=Math.max(0,MAX-n); msg='Combined maximum usage across both scenarios is 4 hours.'; }
  setErr(dgErr,msg); calc();
}
function handleDays(){
  if(days.value===''){ setErr(daysErr,''); calc(); return; }
  let n=parseInt(days.value,10); if(isNaN(n)||n<0){ calc(); return; }
  let msg='';
  if(n>365){ n=365; days.value=n; msg='Maximum operational days allowed is 365.'; }
  setErr(daysErr,msg); calc();
}
function calc(){
  const P=Math.max(0,parseFloat(power.value)||0);
  const sH=Math.max(0,parseFloat(solar.value)||0);
  const dH=Math.max(0,parseFloat(dg.value)||0);
  const D=Math.max(0,parseInt(days.value,10)||0);
  const total=sH+dH;
  const bess=(P*total)/0.81;
  const solarPY=P*sH*D;
  const solarSav=solarPY*3;
  const dgPY=P*dH*D;
  const dgSav=dgPY*20;
  const totalAnn=solarSav+dgSav;
  const capex=bess*19000;
  const payY=totalAnn>0?capex/totalAnn:0;
  const payM=payY*12;
  const net10=totalAnn*10-capex;

  $('k_total').textContent='₹'+fmtINR(totalAnn);
  $('k_payY').textContent=payY.toFixed(2)+' Years';
  $('k_payM').textContent=payM.toFixed(1)+' Months';
  $('k_net').textContent='₹'+fmtINR(net10);
  $('k_solarSav').textContent='₹'+fmtINR(solarSav);
  $('k_dgSav').textContent='₹'+fmtINR(dgSav);
  $('k_bess').textContent=fmtNum(bess,2);
  $('k_capex').textContent='₹'+fmtINR(capex);
  $('k_solarE').textContent=fmtNum(solarPY,0);
  $('k_dgE').textContent=fmtNum(dgPY,0);
}
power.addEventListener('input',calc);
solar.addEventListener('input',handleSolar);
dg.addEventListener('input',handleDg);
days.addEventListener('input',handleDays);
calc();
</script>
</body>
</html>
